// Parse Japanese String with 【 】 into styled HTML
function formatJapaneseText(text) {
    return text.replace(/【(.*?)】/g, '<span class="highlight-jp">$1</span>');
}


// ==========================================
// FURIGANA + MODAL KANJI
// ==========================================
const T={a:'あ',i:'い',u:'う',e:'え',o:'お',ka:'か',ki:'き',ku:'く',ke:'け',ko:'こ',sa:'さ',shi:'し',si:'し',su:'す',se:'せ',so:'そ',ta:'た',chi:'ち',ti:'ち',tsu:'つ',tu:'つ',te:'て',to:'と',na:'な',ni:'に',nu:'ぬ',ne:'ね',no:'の',ha:'は',hi:'ひ',fu:'ふ',hu:'ふ',he:'へ',ho:'ほ',ma:'ま',mi:'み',mu:'む',me:'め',mo:'も',ya:'や',yu:'ゆ',yo:'よ',ra:'ら',ri:'り',ru:'る',re:'れ',ro:'ろ',wa:'わ',wo:'を',ga:'が',gi:'ぎ',gu:'ぐ',ge:'げ',go:'ご',za:'ざ',ji:'じ',zi:'じ',zu:'ず',ze:'ぜ',zo:'ぞ',da:'だ',di:'ぢ',du:'づ',de:'で',do:'ど',ba:'ば',bi:'び',bu:'ぶ',be:'べ',bo:'ぼ',pa:'ぱ',pi:'ぴ',pu:'ぷ',pe:'ぺ',po:'ぽ',
kya:'きゃ',kyu:'きゅ',kyo:'きょ',sha:'しゃ',shu:'しゅ',sho:'しょ',cha:'ちゃ',chu:'ちゅ',cho:'ちょ',nya:'にゃ',nyu:'にゅ',nyo:'にょ',hya:'ひゃ',hyu:'ひゅ',hyo:'ひょ',mya:'みゃ',myu:'みゅ',myo:'みょ',rya:'りゃ',ryu:'りゅ',ryo:'りょ',gya:'ぎゃ',gyu:'ぎゅ',gyo:'ぎょ',ja:'じゃ',jya:'じゃ',jyu:'じゅ',jyo:'じょ',ju:'じゅ',jo:'じょ',bya:'びゃ',byu:'びゅ',byo:'びょ',pya:'ぴゃ',pyu:'ぴゅ',pyo:'ぴょ'};
function romajiToKana(s){
  s=s.toLowerCase().replace(/[\s\-]/g,'');
  let out='',i=0;
  while(i<s.length){
    const c=s[i];
    if(!/[a-z']/.test(c)){out+=c;i++;continue;}
    if(c==="'"){i++;continue;}
    if(c==='n'&&(i+1>=s.length||!/[aiueoy]/.test(s[i+1]))){out+='ん';i++;if(s[i]==="'")i++;continue;}
    if(c===s[i+1]&&!/[aiueon]/.test(c)){out+='っ';i++;continue;}
    let m=null;
    for(const l of [3,2,1]){const k=s.substr(i,l);if(T[k]){m=k;break;}}
    if(!m){out+=c;i++;continue;}
    out+=T[m];i+=m.length;
  }
  return out;
}

const KANJI_RE = /[\u4e00-\u9fff々]/;
const hasKanji = (t) => KANJI_RE.test(t);
const esc = (t) => String(t).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

function buildFurigana(j, r) {
    const segs = j.split('、').map(s => s.trim());
    const reads = r.split(/\s*,\s*/).map(romajiToKana);
    const kIdx = segs.map((s, n) => hasKanji(s) ? n : -1).filter(n => n >= 0);
    let map = {};
    if (reads.length === segs.length) segs.forEach((s, n) => map[n] = reads[n]);
    else if (reads.length === kIdx.length) kIdx.forEach((n, k) => map[n] = reads[k]);
    else kIdx.forEach(n => map[n] = reads[0]);
    const html = segs.map((s, n) => (hasKanji(s) && map[n]) ? `<ruby>${esc(s)}<rt>${esc(map[n])}</rt></ruby>` : esc(s)).join('<span class="mx-1">、</span>');
    const kana = segs.map((s, n) => hasKanji(s) ? map[n] : s).join('、');
    return { html, kana };
}

