// Markup contoh: {kata} / {kata|yomi} = disorot, [kanji|yomi] = hanya furigana
function renderExample(str, item) {
    const re = /\{([^{}|]+)(?:\|([^{}]*))?\}|\[([^\[\]|]+)\|([^\[\]]*)\]/g;
    let out = '', last = 0, m;
    while ((m = re.exec(str)) !== null) {
        out += esc(str.slice(last, m.index));
        if (m[3] !== undefined) {
            out += `<ruby>${esc(m[3])}<rt>${esc(m[4])}</rt></ruby>`;
        } else {
            let reading = m[2];
            if (!reading && hasKanji(m[1]) && m[1] === item.j && !item.j.includes('、')) reading = buildFurigana(item.j, item.r).kana;
            out += '<span class="ex-hl">' + (reading && hasKanji(m[1]) ? `<ruby>${esc(m[1])}<rt>${esc(reading)}</rt></ruby>` : esc(m[1])) + '</span>';
        }
        last = re.lastIndex;
    }
    return out + esc(str.slice(last));
}

function openKanjiModal(item, catId, idx) {
    const kanji = hasKanji(item.j);
    const f = buildFurigana(item.j, item.r);
    document.getElementById('km-word').innerHTML = kanji ? f.html : esc(item.j);
    document.getElementById('km-furi-wrap').classList.toggle('hidden', !kanji);
    document.getElementById('km-furigana').textContent = f.kana;
    document.getElementById('km-romaji').textContent = item.r;
    document.getElementById('km-arti').textContent = item.m;
    const exWrap = document.getElementById('km-ex-wrap');
    const ex = KOTOBA_EXAMPLES[catId + '.' + idx];
    if (ex) {
        const cp = colorPairA(ex.j, item, ex.m);
        document.getElementById('km-ex-jp').innerHTML = cp.jp;
        document.getElementById('km-ex-id').innerHTML = cp.id;
        exWrap.classList.remove('hidden');
    } else exWrap.classList.add('hidden');
    const note = document.getElementById('km-note');
    if (item.note) { note.innerHTML = item.note; note.classList.remove('hidden'); } else note.classList.add('hidden');
    document.getElementById('kanji-modal').classList.add('open');
}
function closeKanjiModal(e) {
    document.getElementById('kanji-modal').classList.remove('open');
}
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeKanjiModal(); });


// ==========================================
// CHECKLIST PENGUASAAN KOTOBA
// ==========================================
let doneSet = new Set();
try { doneSet = new Set(JSON.parse(localStorage.getItem('n5_kotobaDone') || '[]')); } catch (e) {}
function saveDone() { try { localStorage.setItem('n5_kotobaDone', JSON.stringify([...doneSet])); } catch (e) {} }
const itemKey = (catId, idx) => catId + ':' + idx;
function catDoneCount(cat) { return cat.items.filter((_, i) => doneSet.has(itemKey(cat.id, i))).length; }

function updateCategoryProgress() {
    const cat = vocabData.find(c => c.id === currentKotobaCategoryId);
    if (!cat) return;
    const done = catDoneCount(cat), total = cat.items.length;
    document.getElementById('cat-progress-text').textContent = done + '/' + total;
    document.getElementById('cat-progress-bar').style.width = (total ? done / total * 100 : 0) + '%';
    document.getElementById('cat-toggle-all').textContent = done === total ? 'Hapus semua' : 'Centang semua';
}

function toggleItemDone(catId, idx, card, checked) {
    const k = itemKey(catId, idx);
    if (checked) doneSet.add(k); else doneSet.delete(k);
    card.classList.toggle('bg-gray-100', checked);
    saveDone();
    updateCategoryProgress();
}

document.getElementById('cat-toggle-all').addEventListener('click', () => {
    const cat = vocabData.find(c => c.id === currentKotobaCategoryId);
    const allDone = catDoneCount(cat) === cat.items.length;
    cat.items.forEach((_, i) => { allDone ? doneSet.delete(itemKey(cat.id, i)) : doneSet.add(itemKey(cat.id, i)); });
    saveDone();
    renderVocab(cat.id);
});
document.getElementById('reset-progress').addEventListener('click', () => {
    if (!confirm('Hapus semua progress kotoba?')) return;
    doneSet.clear(); saveDone();
    renderVocab(currentKotobaCategoryId);
});

function renderContinue() {
    const cat = vocabData.find(c => c.id === currentKotobaCategoryId) || vocabData[0];
    const d = catDoneCount(cat), t = cat.items.length;
    document.getElementById('hc-title').textContent = cat.title;
    document.getElementById('hc-count').textContent = d + '/' + t + ' dikuasai';
    document.getElementById('hc-bar').style.width = (t ? d / t * 100 : 0) + '%';
    document.getElementById('hc-btn').onclick = () => { if (selectKotobaCategory(cat.id) === false) return; switchView('Kotoba'); };
}

function renderHome() {
    renderContinue();
    renderKanjiHome();
    let done = 0, total = 0;
    const list = document.getElementById('home-cat-list');
    list.innerHTML = '';
    vocabData.forEach(cat => {
        const d = catDoneCount(cat), t = cat.items.length;
        done += d; total += t;
        const pct = t ? Math.round(d / t * 100) : 0;
        const row = document.createElement('button');
        row.className = 'text-left w-full group';
        row.innerHTML = `
            <div class="flex justify-between text-[11px] font-bold uppercase mb-0.5 group-hover:underline">
                <span>${cat.title}${canOpen('kotoba', cat.id) ? '' : ' \uD83D\uDD12'}</span><span class="font-mono">${d}/${t}</span>
            </div>
            <div class="w-full h-2.5 border-2 border-black bg-white"><div class="h-full bg-black" style="width:${pct}%"></div></div>`;
        row.addEventListener('click', () => { if (selectKotobaCategory(cat.id) === false) return; switchView('Kotoba'); });
        list.appendChild(row);
    });
    const pctAll = total ? Math.round(done / total * 100) : 0;
    document.getElementById('home-total-text').textContent = done + '/' + total;
    document.getElementById('home-total-bar').style.width = pctAll + '%';
    document.getElementById('home-total-percent').textContent = pctAll + '%';
}
